<script setup>import {ref} from 'vue';import {state,actions} from '../../domain/prototypeStore.js';import StatusTag from '../../components/StatusTag.vue';const msg=ref('');const advance=()=>{const r=actions.advanceDrill('已完成集合、清点和现场记录');msg.value=r.message||(r.ok?'演练状态已更新':'操作失败')}</script>
<template><section class="h5-page"><div class="h5-module-hero"><span>演</span><h2>{{state.drill.name}}</h2><p>{{state.drill.id}} · {{state.drill.place}}</p></div><div v-if="msg" class="action-message">{{msg}}</div><div class="h5-card"><header><strong>当前状态</strong><StatusTag :text="state.drill.status"/></header><p>责任组：{{state.drill.owner}}</p><p>执行结果：{{state.drill.result||'待提交'}}</p><p>改进措施：{{state.drill.improvement||'待评估'}}</p><button class="primary-button active" :disabled="state.drill.status==='已完成'" @click="advance">{{state.drill.status==='待执行'?'确认开始':state.drill.status==='执行中'?'提交执行结果':state.drill.status==='待评估'?'完成评估':'已完成'}}</button></div></section></template>